from pathlib import Path
import sys, json
ROOT=Path(__file__).resolve().parents[2]
sys.path.insert(0,str(ROOT/'output/new-store-20260920/pdf-libs'))
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.lib import colors
from reportlab.lib.styles import ParagraphStyle
from reportlab.lib.enums import TA_LEFT
from reportlab.lib.pagesizes import A4
from reportlab.lib.units import mm
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak
from xml.sax.saxutils import escape
OUT=ROOT/'output/pdf/BADIZO_NEW_STORE_2026-09-20_TELUGU_ENGLISH.pdf'
OUT.parent.mkdir(parents=True,exist_ok=True)
font='C:/Windows/Fonts/Nirmala.ttc'
pdfmetrics.registerFont(TTFont('Nirmala',font,subfontIndex=0,shapable=True))
pdfmetrics.registerFont(TTFont('NirmalaBold',font,subfontIndex=1,shapable=True))
navy=colors.HexColor('#15324a');teal=colors.HexColor('#007e87')
body=ParagraphStyle('body',fontName='Nirmala',fontSize=10,leading=16,spaceAfter=7,shaping=True,textColor=navy)
te=ParagraphStyle('telugu',parent=body,fontSize=10.3,leading=17,spaceAfter=11,textColor=colors.HexColor('#354655'))
h1=ParagraphStyle('h1',parent=body,fontName='NirmalaBold',fontSize=22,leading=29,spaceAfter=13,textColor=navy)
h2=ParagraphStyle('h2',parent=body,fontName='NirmalaBold',fontSize=12,leading=18,spaceBefore=7,spaceAfter=7,textColor=teal)
small=ParagraphStyle('small',parent=body,fontSize=8.5,leading=13)
story=[]
def p(s,style=body):return Paragraph(escape(s),style)
def title(n,en,tel):
 if story:
  while story and isinstance(story[-1],Spacer):story.pop()
  story.append(PageBreak())
 story.extend([p('BADIZO  /  NEW STORE  /  20 SEPTEMBER 2026',small),Spacer(1,6*mm),p(str(n).zfill(2)+'  '+en,h1),p(tel,h2),Spacer(1,3*mm)])
def pair(en,tel):
 story.extend([p(en),p(tel,te)])
def sub(en,tel=None):
 story.append(p(en,h2))
 if tel:story.append(p(tel,te))
def table(rows,widths=None):
 cells=[[p(str(c),small) for c in row] for row in rows]
 t=Table(cells,colWidths=widths or [58*mm,112*mm],hAlign='LEFT',repeatRows=1)
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e3f1f3')),('VALIGN',(0,0),(-1,-1),'TOP'),('GRID',(0,0),(-1,-1),.4,colors.HexColor('#d7e2e7')),('LEFTPADDING',(0,0),(-1,-1),8),('RIGHTPADDING',(0,0),(-1,-1),8),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6)]))
 story.extend([t,Spacer(1,4*mm)])
title(1,'Installation guide','కొత్త షాపు - తెలుగు & English సూచనలు')
pair('Purpose: install the current Badizo POS on a NEW store server and its client PCs. Start with START_HERE.bat. Copy the entire folder, including payload.','ఈ package కొత్త షాపు కోసం. START_HERE.bat తెరవండి. payloadతో సహా మొత్తం folderను copy చేయాలి. BAT ఒక్కటే copy చేస్తే install కాదు.')
table([['System','Install choice'],['Main server','01_INSTALL_SERVER.bat - MySQL + backend + desktop POS'],['Admin / Admin 1 / Admin 2','02_INSTALL_ADMIN.bat'],['System / Counter 1 to 6','03_INSTALL_COUNTER.bat'],['Security / Gate Pass','04_INSTALL_SECURITY.bat'],['Staff / Payroll office','05_INSTALL_STAFF_PAYROLL.bat - Admin login, then Staff Payroll'],['Connection / printers','06_CHECK_CONNECTION_PRINTERS.bat']])
pair('This setup supports an existing MySQL 8.0 Windows service on port 3306, Running and Automatic. It creates a separate empty store database; existing databases and root password are preserved.','MySQL 8.0 service port 3306లో Running, Automaticగా ఉంటే దానినే వాడుతుంది. కొత్త storeకి వేరే ఖాళీ database సృష్టిస్తుంది. పాత databases, root password మారవు.')
pair('All current modules are included. Physical printer quality, clean-PC startup and site LAN acceptance must still be checked at the new store. Read page 13 before go-live.','ప్రస్తుత modules అన్నీ packageలో ఉన్నాయి. కొత్త PC startup, LAN, అసలు printer outputలను కొత్త షాపులో పరీక్షించాలి. Live sales ముందు 13వ పేజీ చూడండి.')
title(2,'Prepare the new store','Install ముందు సిద్ధం చేసుకోవాల్సినవి')
pair('1. Use Windows x64 PCs. Recommended server: 8 GB RAM, SSD, at least 6 GB free on C: plus space for sales and backups. Connect the server to power/UPS and wired LAN.','1. Windows x64 PC వాడాలి. Serverకి 8 GB RAM, SSD, C:లో కనీసం 6 GB ఖాళీతో పాటు data/backup స్థలం ఉంచండి. UPS, LAN cable కలపండి.')
pair('2. Connect the shop LAN. Setup fixes the selected server adapter at 192.168.1.10 / 255.255.255.0. Exclude .10 from router DHCP. If multiple adapters are active, choose the shop LAN adapter.','2. Shop LAN కలపండి. Server adapterను setup 192.168.1.10 / 255.255.255.0కి మారుస్తుంది. Router DHCPలో .10 ఇవ్వకుండా ఉంచండి. Adapters ఎక్కువ ఉంటే shop LAN ఎంచుకోండి.')
pair('3. On the trusted shop network, open Windows Settings > Network & Internet > Ethernet/Wi-Fi > Network profile and select Private. Do not choose a public/guest network.','3. షాపు trusted networkలో Network & Internet > Ethernet/Wi-Fi > Network profileలో Private ఎంచుకోండి. Guest/Public network వాడవద్దు.')
pair('4. Copy the complete package to a local folder on each PC. Do not run from inside a ZIP. Run 07_VERIFY_PACKAGE.bat; all files must show VERIFIED before installation.','4. పూర్తి folderను ప్రతి PCలో local diskకి copy చేయండి. ZIP లోపలి నుంచే run చేయవద్దు. 07_VERIFY_PACKAGE.bat run చేసి VERIFIED వచ్చిందో చూడండి.')
pair('5. Install the correct Windows drivers for the actual thermal, barcode and A4 printers on the PC that owns each printer. Keep paper/labels and a barcode scanner ready.','5. Printer ఉన్న PCలో ఆ modelకి సరైన thermal, barcode, A4 Windows drivers install చేయండి. Paper/labels, scanner సిద్ధంగా ఉంచండి.')
pair('Bundled: Node, MySQL, VC++ runtime and desktop app. Installation and local POS work over LAN without internet. Bring model-specific printer drivers on USB. Online messaging, cloud and external gateways stay unavailable offline.','Node, MySQL, VC++, POS app packageలో ఉన్నాయి. Install, local POSకి LAN చాలు. Printer model drivers USBలో తెచ్చుకోండి. Internet లేకుండా cloud/messages/external gateways పనిచేయవు.')
title(3,'Install the SERVER first','మొదట main server install చేయండి')
pair('1. Sign in to Windows as the store operator. Open the package and double-click 01_INSTALL_SERVER.bat (or START_HERE > 1). Accept the Windows UAC Administrator prompt.','1. Store operator Windows accountలోకి వెళ్లి 01_INSTALL_SERVER.bat double-click చేయండి. లేదా START_HEREలో 1 ఎంచుకోండి. UACలో Yes ఇవ్వండి.')
pair('2. Existing MySQL: setup reuses its service (usually MySQL80), asks for the MySQL admin username and hidden password, then creates a separate database. With no MySQL service, setup installs bundled BadizoMySQL.','2. MySQL ఇప్పటికే ఉంటే అదే serviceను వాడి admin username, దాచిన password అడుగుతుంది. తర్వాత కొత్త database తయారు చేస్తుంది. MySQL లేకపోతే bundled BadizoMySQL install చేస్తుంది.')
pair('3. Enter the MySQL password locally. New application credentials are saved in C:/BadizoPOS/NEW_STORE_CREDENTIALS.txt (Administrator only).','3. MySQL password setupలోనే ఇవ్వండి. కొత్త application credentials NEW_STORE_CREDENTIALS.txtలో ఉంటాయి; Administrator మాత్రమే చదవగలరు.')
pair('4. Setup registers Badizo POS Backend in Windows Task Scheduler, checks database tables and the frontend, and installs the current desktop app for the original Windows user.','4. Windows Task Schedulerలో Badizo POS Backend task ఏర్పడుతుంది. Database tables, frontend తనిఖీ చేసి, Windows userకి desktop app install అవుతుంది.')
pair('5. Continue only after SERVER READY and READY: open Badizo POS appear. Note the computer name/IP printed by setup; C:\\BadizoPOS\\SERVER_CONNECTION.json also contains it.','5. SERVER READY, READY: open Badizo POS వచ్చాక మాత్రమే ముందుకు వెళ్లండి. చూపిన server పేరు/IP రాసుకోండి. SERVER_CONNECTION.jsonలో కూడా ఉంటుంది.')
pair('6. Open Badizo POS on the desktop. Log in using server / server123 for first setup. Restart the PC once and confirm the login screen returns without manually starting a BAT.','6. Desktop Badizo POS తెరిచి మొదట server / server123తో login అవ్వండి. ఒకసారి PC restart చేసి BAT run చేయకుండానే login screen వస్తుందో చూడండి.')
pair('If setup fails: read C:\\BadizoPOS\\installation.log and mysql-error.log. Correct the problem and rerun the same BAT. Never delete mysql-data to “fix” a partially installed server.','Setup fail అయితే installation.log, mysql-error.log చూడండి. సమస్య సరిచేసి అదే BAT మళ్లీ run చేయండి. mysql-data folderను delete చేయవద్దు.')
title(4,'Install client PCs','Admin, Counter, Security, Payroll PCs')
pair('1. Keep the new server running. On each client PC, sign in as its normal Windows user. Open the full copied package and choose the required BAT.','1. కొత్త server ONలో ఉంచండి. ప్రతి client PCలో సాధారణ Windows userతో login అయి, copy చేసిన పూర్తి folderలో సరైన BAT తెరవండి.')
pair('2. Clients automatically connect to 192.168.1.10:5000. Use any unique reachable LAN IP, normally 192.168.1.2-254 except .10. DHCP is fine. Another subnet needs LAN routing; internet is unnecessary.','2. Clients ఆటోమేటిక్\u200cగా 192.168.1.10:5000కి connect అవుతాయి. సాధారణంగా .10 తప్ప 192.168.1.2-254లో unique IP లేదా DHCP వాడండి. వేరే subnet అయితే LAN routing కావాలి; internet అవసరం లేదు.')
pair('3. Admin: choose admin, admin1 or admin2. Counter: choose system number 1 to 6. The login screen then fixes the system and lets the authorized counter mapping be chosen.','3. Adminలో admin/admin1/admin2 ఎంచుకోండి. Counterలో system number 1–6 ఇవ్వండి. Login screenలో system, counter mapping సరిగా ఉన్నాయో తనిఖీ చేయండి.')
pair('4. Security opens Security login for Gate Pass. Payroll opens Admin login; select Staff Payroll after login. Payroll is an existing POS module, not a separate restricted employee login.','4. Securityలో Gate Pass login వస్తుంది. Payrollలో Admin login తర్వాత Staff Payroll ఎంచుకోవాలి. ఇది POSలో module; ప్రత్యేక పరిమిత employee login కాదు.')
pair('5. Wait for READY. Open the Badizo POS desktop shortcut. Do not open the payload installer directly: the BAT writes the correct server and role settings.','5. READY వచ్చాక desktop shortcut తెరవండి. payload installerను నేరుగా run చేయవద్దు. BAT సరైన server/role settings రాస్తుంది.')
pair('6. Run 06_CHECK_CONNECTION_PRINTERS.bat on every PC. Verify SERVER + UI OK and the printer list. A printer appearing in this list is not proof of a successful physical print.','6. ప్రతి PCలో connection/printer check BAT run చేయండి. SERVER + UI OK, printer list చూడండి. Listలో కనిపించడం మాత్రమే print పనిచేస్తుందని నిర్ధారణ కాదు.')
title(5,'First login and store setup','కొత్త షాపు వివరాలు తప్పనిసరిగా నమోదు చేయండి')
table([['Role / username','Initial password'],['server','server123'],['admin / admin1 / admin2','admin123'],['counter1 ... counter6','Same as username: counter1 ... counter6'],['security / security1 / security2','admin123']])
pair('1. In System, enter your new shop name, address, phone, GSTIN, bank account, IFSC, branch and UPI details. Save, reopen the screen and verify. Do not sell with NEW STORE - CONFIGURE SYSTEM still displayed.','1. Systemలో కొత్త shop పేరు, చిరునామా, phone, GSTIN, bank account, IFSC, branch, UPI నమోదు చేసి Save చేయండి. మళ్లీ తెరిచి చూడండి. NEW STORE అని ఉన్నప్పుడే sales మొదలుపెట్టవద్దు.')
pair('2. In user management, change the default passwords. Log out and confirm the new password works and the old one is rejected. Keep Server/Admin passwords with authorized staff only.','2. User managementలో default passwords మార్చండి. Logout చేసి కొత్త password పనిచేస్తుందో, పాతది తిరస్కరిస్తుందో చూడండి. Server/Admin passwords బాధ్యతగల staff వద్దే ఉంచండి.')
pair('3. Set counter count and verify each S/C pairing at login. Create/import only this store’s products and opening stock. Validate product code, name, unit, HSN, tax, MRP, selling price and purchase unit.','3. Counter count, ప్రతి S/C mapping తనిఖీ చేయండి. ఈ shop products, opening stock మాత్రమే నమోదు/import చేయండి. Code, name, unit, HSN, tax, MRP, rate, purchase unit సరిచూడండి.')
pair('4. Configure receipt width, default print mode, actual printer names and store-specific footer/exchange terms. Save a sample PDF and ensure it contains this store’s identity only.','4. Receipt width, print mode, అసలు printer పేర్లు, footer/exchange terms నమోదు చేయండి. Sample PDFలో ఈ shop వివరాలే ఉన్నాయో చూడండి.')
pair('The package contains no existing customer, invoice, stock or staff database. Demo/QA data used during validation is excluded.','ఈ packageలో పాత customer, invoice, stock, staff database లేదు. పరీక్షల కోసం వాడిన QA data కూడా చేర్చలేదు.')
title(6,'POS sale acceptance','Sale నుంచి stock/report వరకు పరీక్షించండి')
pair('1. Add one clearly marked test product with known stock and price. Log in to the intended system/counter. Scan the barcode and verify quantity, price, tax and total before saving.','1. తెలిసిన stock/rateతో test product నమోదు చేయండి. సరైన system/counterలో login అయి barcode scan చేయండి. Save ముందు quantity, rate, tax, total తనిఖీ చేయండి.')
pair('2. Test Cash with exact payment and change. Then test UPI, Card and Mixed as permitted. Do not record a real digital payment unless it was actually received.','2. Cash exact amount, change రెండూ పరీక్షించండి. తర్వాత UPI/Card/Mixed పరీక్షించండి. నిజంగా రాని digital paymentను real saleగా నమోదు చేయవద్దు.')
pair('3. Record the saved invoice number. Open bill history/details and verify the same number, total, counter label and payment. Stock must reduce once for a sale.','3. Save అయిన invoice number రాసుకోండి. Bill history/detailsలో అదే number, total, counter label, payment ఉన్నాయో చూడండి. Saleకి stock ఒక్కసారే తగ్గాలి.')
pair('4. If saving times out, search for the bill first. Repeatedly pressing Save or creating a new bill before checking can cause operational duplicates. The tested request retry path reuses its saved invoice.','4. Save timeout అయితే ముందుగా bill search చేయండి. నిర్ధారించకుండా కొత్త bill చేయవద్దు. పరీక్షించిన retry flowలో అదే saved invoice తిరిగి వస్తుంది.')
pair('5. Test Hold/Recall, quantity change, free-item offers, exchange/return and authorized void on designated test transactions. Confirm stock and reports after each. These business variants still need site acceptance.','5. Test transactionsతో Hold/Recall, quantity change, free offers, exchange/return, authorized void పరీక్షించండి. ప్రతిసారి stock/reports చూడండి. ఈ variantsకు site acceptance అవసరం.')
pair('6. Reconcile daily sales with Cash/UPI/Card totals and counter closing. Use the documented void/return workflow to identify test transactions before live trading; do not directly edit the database.','6. Daily salesను Cash/UPI/Card, counter closingతో సరిపోల్చండి. Live trading ముందు test billsను సరైన void/return workflowతో గుర్తించండి. Databaseను నేరుగా మార్చవద్దు.')
title(7,'Thermal receipt setup','Thermal printer - ప్రతి counterలో')
pair('1. Connect the thermal printer and install its manufacturer driver. Windows Settings > Printers & scanners > select printer > Print a test page. Confirm paper width and cutter work.','1. Thermal printer కలిపి manufacturer driver install చేయండి. Windowsలో ఆ printerకి test page ఇవ్వండి. Paper width, cutter పనిచేస్తున్నాయో చూడండి.')
pair('2. Use the installed Badizo desktop app for native printing. Set the intended printer and the correct 58/80 mm width where supported; do not assume the Windows default is the correct printer.','2. Native printingకి Badizo desktop app వాడండి. సరైన printer, అందుబాటులో ఉన్న 58/80 mm width ఎంచుకోండి. Windows default సరైనదని అనుకోకండి.')
pair('3. Print one short test bill. Check store name, GSTIN, invoice number, S/C label, items, quantity, taxes, total, received amount, change and footer. Confirm exactly one receipt.','3. ఒక చిన్న test bill print చేయండి. Shop పేరు, GSTIN, invoice, S/C, items, quantity, tax, total, received, change, footer చూడండి. ఒక్క receipt మాత్రమే రావాలి.')
pair('4. Print one long bill with enough items to exceed the short receipt height. Check the bottom totals are visible, lines are not cut off and no unexpected blank roll feeds.','4. ఎక్కువ itemsతో long bill print చేసి చివరి totals కనిపిస్తున్నాయో, lines cut అవుతున్నాయో, ఎక్కువ blank paper వస్తుందో చూడండి.')
pair('5. Use Reprint on an already saved invoice. Check it is labelled as a reprint and that no second invoice or stock deduction is created.','5. Saved invoiceకి Reprint వాడండి. Reprint label ఉందో, కొత్త invoice/మరొక stock deduction జరగలేదో చూడండి.')
pair('If print fails, inspect the printer queue and physical printer before retrying. Do not save a second sale just to obtain the first sale’s receipt.','Print fail అయితే ముందుగా queue, printer చూడండి. Receipt కోసం మళ్లీ sale save చేయవద్దు.')
title(8,'Barcode label setup','Barcode labels, calibration, stock')
pair('1. Install the correct TSC or compatible driver on the printer PC. Configure label width, height, gap and sensor calibration for the actual roll. Print the manufacturer test label first.','1. Printer PCలో సరైన TSC/compatible driver install చేయండి. అసలు rollకి width, height, gap, sensor calibration సెట్ చేయండి. ముందుగా manufacturer test label ఇవ్వండి.')
table([['Template file','Intended layout'],['tsc-244-1-33x25-single.prn','38 x 25 mm Two-Up (legacy filename; verify actual label)'],['tsc-te244-40x40-two-up.prn','40 x 40 mm Two-Up'],['tsc-244-pro-50x50-two-up.prn','50 x 50 mm Two-Up'],['tsc-244-2-jewellery-100x15-tail.prn','100 x 15 mm Jewellery Tail']])
pair('2. In Barcode, select the actual printer/template. Enter the product, barcode, MRP/rate, pack/quantity and label count. Start with 1 or 2 labels; verify alignment and scan them back into POS.','2. Barcodeలో సరైన printer/template, product, barcode, MRP/rate, pack/quantity, label count ఇవ్వండి. మొదట 1–2 labelsతో alignment, scanner reading పరీక్షించండి.')
pair('Important current behavior: generating labels through the PRN route increases product stock by the sticker count and records a stock adjustment. It is not a stock-neutral preview/reprint.','ముఖ్యమైన ప్రస్తుత ప్రవర్తన: PRN route ద్వారా labels generate చేస్తే sticker count మేరకు stock పెరుగుతుంది, stock adjustment నమోదవుతుంది. ఇది stock మారని preview/reprint కాదు.')
pair('Check stock before/after label generation. Do not repeatedly generate labels to fix alignment on a real product without accounting for this stock change. Use a test product for calibration.','Labels generate ముందు/తర్వాత stock చూడండి. Alignment కోసం real productపై పదే పదే generate చేయవద్దు. Calibrationకి test product వాడండి.')
pair('All four PRN templates passed software generation checks. Physical label size, gap, darkness and scanner readability must be approved on the store’s printer.','నాలుగు PRN templates software generation checks పాస్ అయ్యాయి. Label size, gap, darkness, scan readabilityను shop printerపై నిర్ధారించాలి.')
title(9,'A4 and PDF output','A4 bill, PDF save, reprint')
pair('1. Install the A4 printer driver and print a Windows test page. Select A4 paper and portrait orientation. In POS choose the A4 invoice mode for a saved test bill.','1. A4 printer driver install చేసి Windows test page ఇవ్వండి. A4 paper, portrait ఎంచుకోండి. POSలో saved test billకి A4 mode ఎంచుకోండి.')
pair('2. Use the bill’s PDF option to save a file to a known folder. Open the PDF and verify the invoice number, date, buyer, GST breakup, bank details, amount in words and totals.','2. Bill PDF optionతో తెలిసిన folderలో save చేయండి. PDF తెరిచి invoice, date, buyer, GST breakup, bank details, amount in words, totals చూడండి.')
pair('3. Print one A4 copy at actual size / 100% where appropriate. Check margins, table borders and the last total/signature section. Avoid printing from both the app and the PDF viewer unintentionally.','3. ఒక A4 copy print చేసి margins, table borders, చివరి total/signature చూడండి. App, PDF viewer రెండింటి నుంచి అనుకోకుండా print ఇవ్వవద్దు.')
pair('4. Test a long invoice across pages and a short invoice on one page. Check that all items appear once and the final totals are complete.','4. Long invoice multi-page, short invoice single-page రెండూ పరీక్షించండి. Items ఒక్కొక్కసారి, final totals పూర్తిగా ఉన్నాయో చూడండి.')
pair('5. Reopen the saved invoice and use Reprint. Saving a PDF or reprinting must not create another sale or reduce stock again. Verify this from bill history and stock.','5. Saved invoice తెరిచి Reprint వాడండి. PDF save/reprint వల్ల మరో sale లేదా stock deduction జరగకూడదు. History/stockలో నిర్ధారించండి.')
pair('Report export formats depend on the screen. Use its own PDF/Excel/CSV/Print action; do not assume every report provides every format.','Reportకి అందుబాటులో ఉన్న PDF/Excel/CSV/Print action మాత్రమే వాడండి. ప్రతి reportలో అన్ని formats ఉంటాయని అనుకోకండి.')
title(10,'Reports and ledger books','అన్ని modules ఉన్నాయి - totals సరిపోల్చండి')
table([['Area','Checks at the new store'],['Sales reports','Daily/monthly sales, POS sale report, counter sale slip, handover, reprints, exchange bills'],['Tax / archive','GST-HSN, tax summary, GSTR1/2/3, financial-year archive and invoice details'],['Stock / products','Stock, product sales, top products, expiry, reorder, import history, mass updates'],['Books','Summary, day book, accounting books, named ledgers, counter cash ledger'],['Purchases / accounts','Inward, suppliers, dues/payments, purchase orders, local/non-local accounts'],['Operations','Counter closing, orders/quotations, customers/loyalty, Security Gate Pass, user/system controls']])
pair('1. Set the correct date range, financial year and counter filters. Compare daily sale totals with saved invoices and each payment mode.','1. Date range, financial year, counter filters సరిగా పెట్టండి. Daily sales totalsను saved invoices, payment modesతో సరిపోల్చండి.')
pair('2. In Ledger Books, verify opening balance + receipts - payments = closing balance according to the screen’s debit/credit convention. Check the latest named-ledger detail edits.','2. Ledger Booksలో screen debit/credit పద్ధతి ప్రకారం opening, receipts, payments, closing balance సరిపోల్చండి. Named-ledger details మార్పులు కూడా చూడండి.')
pair('3. Check counter-closing cash, handover and cash ledger on the same date/counter. An edited description must not create another monetary posting.','3. ఒకే date/counterకి closing cash, handover, cash ledger చూడండి. Description edit వల్ల అదనపు amount posting రాకూడదు.')
pair('4. Export a representative report and compare its total to the on-screen total. Check role restrictions and server approvals where required.','4. ఒక report export చేసి screen totalతో సరిపోల్చండి. Role restrictions, అవసరమైన server approvals పరీక్షించండి.')
title(11,'Staff and payroll','Staff నమోదు నుంచి salary slip వరకు')
pair('1. Install the Payroll client or use Server/Admin. Log in and open Staff Payroll. Create a test employee with a unique code, name, salary type and applicable rate.','1. Payroll client లేదా Server/Adminతో login అయి Staff Payroll తెరవండి. Unique code, name, salary type, rateతో test employee నమోదు చేయండి.')
pair('2. Enter attendance with the correct date: Present, Half Day, Absent, Paid Leave or Week Off. Add overtime and any authorized wage override carefully.','2. సరైన dateకి Present/Half Day/Absent/Paid Leave/Week Off నమోదు చేయండి. Overtime, అనుమతించిన wage override జాగ్రత్తగా ఇవ్వండి.')
pair('3. Choose the salary month. Verify attendance days, basic pay, overtime, earnings, advances and deductions. Statutory rates/amounts must be entered and reviewed by the responsible payroll person.','3. Salary month ఎంచుకుని attendance days, basic pay, overtime, earnings, advances, deductions చూడండి. చట్టపరమైన rates/amountsను payroll బాధ్యుడు నమోదు చేసి తనిఖీ చేయాలి.')
pair('4. Save as Pending while reviewing. Mark Paid only for an actual payment and choose its payment mode/date/reference. Verify the cash-ledger posting and avoid duplicate payment.','4. Review సమయంలో Pendingగా save చేయండి. నిజంగా payment చేసినప్పుడే Paid ఎంచుకుని mode/date/reference ఇవ్వండి. Ledger posting చూడండి; రెండోసారి చెల్లించవద్దు.')
pair('5. Search the employee/code and month/date range. Open the payslip preview and print A4 or save via the available print/PDF workflow. Confirm name, month, earnings, deductions and net salary.','5. Employee/code, month/date rangeతో search చేసి payslip preview తెరవండి. A4 print/PDF workflowతో save చేయండి. Name, month, earnings, deductions, net salary చూడండి.')
pair('Software test completed: daily wage 500 + 2 overtime hours at 62.50 = 625; repeating the Paid save produced one salary-ledger posting. Monthly/hourly, statutory and site-specific cases require payroll acceptance.','Software testలో daily wage 500 + 2 గంటల overtime (62.50) = 625 వచ్చింది. Paid save repeat చేసినా ledgerలో ఒక్క posting వచ్చింది. Monthly/hourly, statutory, shop-specific casesను payroll బాధ్యుడు పరీక్షించాలి.')
title(12,'Backup, restart and recovery','Backup ఉందో తప్పనిసరిగా చూసుకోండి')
pair('1. Windows task Badizo Daily Local Backup runs at 09:00 server local time. If powered off, it catches up after startup; sleep wake depends on Windows support. Confirm Windows time/timezone and keep the server available.','1. Badizo Daily Local Backup task server time ప్రకారం ఉదయం 9కి run అవుతుంది. PC ఆఫ్ అయితే startup తర్వాత backup అవుతుంది. Sleep wake Windowsపై ఆధారపడుతుంది. Time/timezone సరిచూడండి.')
pair('2. Use 08_BACKUP_NOW.bat on the SERVER for a full local ZIP. Check C:\\BadizoPOS\\backups: database.sql, barcode templates, generated PRN output and thermal files are archived. Copy the ZIP to a separate disk.','2. SERVERలో 08_BACKUP_NOW.batతో పూర్తి ZIP తీసుకోండి. backups folderలో SQL, barcode templates/output PRN, thermal files ఉంటాయి. ZIPను వేరే diskకు copy చేయండి.')
pair('3. Reboot the server. Confirm MySQL80 (existing setup) or BadizoMySQL (bundled setup) is Running/Automatic. Check Badizo POS Backend and Badizo Daily Local Backup tasks, then reconnect a client.','3. Restart తర్వాత MySQL80 లేదా BadizoMySQL service Running/Automaticగా ఉందో చూడండి. Backend, Daily Local Backup tasks తనిఖీ చేసి client మళ్లీ connect చేయండి.')
pair('4. Extract a backup ZIP to a separate folder; test database.sql restore only on an isolated installation. Restore barcode templates/output and thermal files separately as needed. A live restore needs current backup and closed sales.','4. ZIP extract చేసి database.sqlను ముందుగా test installationలో restore చేయండి. Barcode/thermal files అవసరమైతే వేరుగా restore చేయండి. Live restore ముందు backup తీసుకుని sales ఆపాలి.')
pair('5. Automatic backup writes last-local-backup.json only after ZIP verification. Failures go to backup-errors.log and Task Scheduler retries. The System > Backup button creates SQL only; use the supplied BAT for SQL + PRN.','5. ZIP check తర్వాతే last-local-backup.json రాస్తుంది. Fail అయితే backup-errors.log చూడండి; task retry చేస్తుంది. System > Backup SQL మాత్రమే; SQL + PRN కోసం ఇచ్చిన BAT వాడండి.')
title(13,'Validation and go-live record','పరీక్షించినవి / ఇంకా siteలో పరీక్షించాల్సినవి')
pair('Automated validation: backend regression tests, frontend regression tests, production build, fresh isolated MySQL schema, role logins, sale/stock/retry, report/book APIs, all four PRN templates, payroll and backup/restore. Exact results are in VALIDATION_REPORT.md.','Automated testsలో backend/frontend, production build, ఖాళీ MySQL schema, roles, sale/stock/retry, report/book APIs, నాలుగు PRN templates, payroll, backup/restore పరీక్షించాం. ఖచ్చితమైన ఫలితాలు VALIDATION_REPORT.mdలో ఉన్నాయి.')
pair('This is not a claim that every feature combination or physical device has passed. Existing automated tests and representative integration flows do not replace site acceptance.','ప్రతి feature combination, physical device పరీక్ష పూర్తయిందని ఇది అర్థం కాదు. Automated tests, representative flowsతో పాటు site acceptance తప్పనిసరి.')
table([['Required new-store check','Technician / result / date'],['Fresh PC server install and reboot','________________________________'],['All client systems / S-C mapping','________________________________'],['Thermal short + long + reprint','________________________________'],['Barcode alignment + scan + stock','________________________________'],['A4 single + multi-page / PDF totals','________________________________'],['Sales / reports / books reconciliation','________________________________'],['Payroll approval and sample payslip','________________________________'],['Backup and isolated restore','________________________________']])
pair('Keep the package, guide and checksum manifest together. Do not use this fresh installer to overwrite the current live store. No existing live-store installation or printer settings were changed while preparing the package.','Package, guide, checksum manifest కలిపి ఉంచండి. ప్రస్తుతం live storeపై ఈ fresh installer run చేయవద్దు. Package సిద్ధం చేసే సమయంలో live installation/printer settings మార్చలేదు.')
sub('Technical references')
story.append(p('MySQL initialization: https://dev.mysql.com/doc/mysql-installation-excerpt/8.0/en/data-directory-initialization.html',small))
story.append(p('Microsoft VC++ runtime: https://learn.microsoft.com/en-us/cpp/windows/latest-supported-vc-redist',small))
title(14,'New SKU Excel upload','Excel నుంచి కొత్త products నమోదు')
pair('1. Open NEW_SKU_UPLOAD.xlsx from this package. Keep Upload as the first sheet and keep row 1 unchanged. Fill your products from row 2; the template has no sample products on the upload sheet.','1. Packageలో NEW_SKU_UPLOAD.xlsx తెరవండి. Upload మొదటి sheetగా, row 1 headers అలాగే ఉంచండి. Row 2 నుంచి మీ products ఇవ్వండి. Uploadలో sample data లేదు.')
pair('2. Keep Product Code, Barcode and HSN as Text so leading zeros survive. Give unique codes and a description. Fill Unit, measure, prices, mandatory GST (enter 0 for zero tax) and purchase-unit conversion; the Guide sheet explains every column.','2. Code, barcode, HSN Textగా ఉంచండి; ముందు సున్నాలు పోవద్దు. Unique codes, పేరు, unit, measure, ధరలు, tax, purchase conversion ఇవ్వండి. Guide sheetలో వివరాలు ఉన్నాయి.')
pair('3. Save as .xlsx. Sign in as Server/Admin, open Inventory and choose Excel/CSV import. Select the saved file and review the confirmation. Check Import History until Completed; inspect skipped/error rows.','3. .xlsxగా save చేయండి. Server/Adminతో Inventoryలో Excel/CSV import ఎంచుకోండి. File ఎంచుకుని confirmation చూసి import చేయండి. Import Historyలో complete అయ్యేవరకు చూసి errors సరిచూడండి.')
pair('4. Inward Quantity ADDS stock each time. Reimporting the same quantity adds it again. For price-only updates use 0. PRN generation also adds sticker-count stock: when labels provide opening stock, import 0 first.','4. Inward Quantity ప్రతిసారీ stockకు చేరుతుంది. అదే quantity మళ్లీ import చేస్తే మళ్లీ పెరుగుతుంది. Rate updateకి 0 ఇవ్వండి. PRNలో sticker count కూడా stockకు చేరుతుంది; labels ద్వారా opening stock వేస్తే Excelలో 0 ఇవ్వండి.')
pair('5. Start with two test SKUs. Verify codes, prices, tax and stock, generate one PRN, print/scan one label and verify stock again. Then import your full master once. Bundled PRN templates are in payload/app/barcode/templates.','5. మొదట రెండు test SKUs import చేసి code, rate, tax, stock చూడండి. ఒక PRN తయారు చేసి label print/scan చేసి stock మళ్లీ చూడండి. తర్వాత పూర్తి master ఒక్కసారి import చేయండి. PRN templates packageలో ఉన్నాయి.')

